-- ---------------------------------------------------------------------------
-- שם טוב — phase 5: verified Hebrew meanings, replacing the seed catalogue.
--
-- Run once in the Supabase SQL Editor, after 2026-09-shem-tov-phase4-catalogue.sql.
--
-- What this does, and why it's an upsert rather than a wipe-and-reinsert:
--
-- The new curated dataset shares 176 of its 200 names with the phase-4
-- seed, and differs on 24. A family may already have voted on a phase-4
-- catalogue name — deleting and reinserting all 200 rows would generate new
-- ids for names that already exist, and CASCADE-delete any votes already
-- cast on them. Instead this UPSERTs by name text: the 176 overlapping
-- names keep their existing id (and therefore keep any votes already cast
-- on them) while every column gets refreshed to the new, verified values;
-- the 24 new names are inserted fresh.
--
-- The 24 phase-4 names that are NOT in the new curated set are then
-- deleted — the task calls for the CSV to be the source of truth, and
-- keeping stale, non-curated rows around contradicts that. Read the
-- warning above the DELETE below before running this migration: if any
-- family has already voted on one of those 24 names, this migration
-- removes those votes along with the name (foreign-key CASCADE). Given how
-- recently the catalogue was first seeded, that's expected to affect zero
-- real votes — but it is a real, if unlikely, side effect worth knowing
-- about before you run this.
-- ---------------------------------------------------------------------------

alter table public.names
  add column if not exists meaning_he         text,
  add column if not exists greek              boolean not null default false,
  add column if not exists meaning_source      text,
  add column if not exists meaning_confidence  text
    check (meaning_confidence is null or meaning_confidence in ('verified', 'uncertain'));

create index if not exists names_greek_idx on public.names (id) where greek;

-- Needed as the ON CONFLICT arbiter below: catalogue names (family_id is
-- null) must be unique by text so an upsert can find "the same name" to
-- update; a family's own suggestions (family_id not null) are untouched by
-- this and may still duplicate any text freely, same as before.
create unique index if not exists names_catalogue_text_unique
  on public.names (text) where family_id is null;

insert into public.names (
  text, gender, origin, length, syllables,
  biblical, hebrew, israeli, international, arabic, european, greek,
  meaning_love, meaning_nature, meaning_light, meaning_strength, meaning_joy, meaning_freedom,
  style_classic, style_modern, style_unique, style_soft, style_traditional, style_vintage,
  popularity, popularity_score,
  short, easy_in_english, works_internationally,
  starts_with, ends_with,
  meaning_he, meaning_source, meaning_confidence
)
