  biblical = excluded.biblical,
  hebrew = excluded.hebrew,
  israeli = excluded.israeli,
  international = excluded.international,
  arabic = excluded.arabic,
  european = excluded.european,
  greek = excluded.greek,
  meaning_love = excluded.meaning_love,
  meaning_nature = excluded.meaning_nature,
  meaning_light = excluded.meaning_light,
  meaning_strength = excluded.meaning_strength,
  meaning_joy = excluded.meaning_joy,
  meaning_freedom = excluded.meaning_freedom,
  style_classic = excluded.style_classic,
  style_modern = excluded.style_modern,
  style_unique = excluded.style_unique,
  style_soft = excluded.style_soft,
  style_traditional = excluded.style_traditional,
  style_vintage = excluded.style_vintage,
  popularity = excluded.popularity,
  popularity_score = excluded.popularity_score,
  short = excluded.short,
  easy_in_english = excluded.easy_in_english,
  works_internationally = excluded.works_internationally,
  starts_with = excluded.starts_with,
  ends_with = excluded.ends_with,
  meaning_he = excluded.meaning_he,
  meaning_source = excluded.meaning_source,
  meaning_confidence = excluded.meaning_confidence;

-- ---------------------------------------------------------------------------
-- Extend family_name_rankings with the new meaning fields, so the ranking
-- screen's cards can show the real curated meaning too, not just browse.
-- CREATE OR REPLACE VIEW with the same column set plus two more at the end
-- is safe — existing columns keep their position, nothing that already
-- reads this view breaks.
-- ---------------------------------------------------------------------------

create or replace view public.family_name_rankings
with (security_invoker = true) as
select
  v.family_id,
  n.id                       as name_id,
  n.text,
  n.gender,
  n.origin,
  n.family_id                as suggested_for_family_id,
  count(distinct v.user_id)  as vote_count,
  max(v.created_at)          as last_voted_at,
  n.meaning_he,
  n.meaning_confidence
from public.name_votes v
join public.names n on n.id = v.name_id
group by v.family_id, n.id, n.text, n.gender, n.origin, n.family_id, n.meaning_he, n.meaning_confidence;

grant select on public.family_name_rankings to authenticated;


-- ---------------------------------------------------------------------------
-- Remove catalogue names that are NOT in the curated set above.
--
-- WARNING: this CASCADE-deletes any votes already cast on one of these 24
-- names (name_votes.name_id references names.id on delete cascade). See the
-- note at the top of this file.
-- ---------------------------------------------------------------------------

delete from public.names
where family_id is null
  and text not in (
    'אביגיל', 'אדם', 'אגם', 'אדר', 'אורי', 'אור', 'אורן', 'אייל', 'איילה', 'איתן', 'אלון', 'אלה', 'אלי', 'אליהו', 'אלעד', 'אמיר', 'אריאל', 'ארי', 'אריה', 'ארז', 'אסף', 'אופק', 'אופיר', 'אפרת', 'בר', 'ברק', 'בתיה', 'בתאל', 'גאיה', 'גדי', 'גיא', 'גיל', 'דניאל', 'דנה', 'דוד', 'דור', 'דביר', 'דרור', 'הדס', 'הדר', 'הלל', 'הראל', 'הילה', 'ורד', 'זוהר', 'זיו', 'חגי', 'חיים', 'טל', 'טלי', 'יאיר', 'יעל', 'יובל', 'יהלי', 'יהונתן', 'יונתן', 'יואב', 'יוסף', 'יסמין', 'ליאור', 'ליבי', 'ליה', 'לב', 'לי', 'מיכאל', 'מיכל', 'מור', 'נועה', 'נועם', 'נבו', 'נטע', 'נויה', 'נעמי', 'עדי', 'עידן', 'עמית', 'עמנואל', 'ענבר', 'עומר', 'עומרי', 'עופרי', 'רוני', 'רון', 'רפאל', 'רומי', 'רות', 'שחר', 'שקד', 'שירה', 'שירי', 'תבור', 'תמר', 'תום', 'תומר', 'אבנר', 'אבישי', 'אוריאל', 'אלכס', 'אמילי', 'בארי', 'בן', 'בנימין', 'גפן', 'גילי', 'יהב', 'לוטם', 'לוטן', 'מאי', 'מילי', 'סהר', 'סיוון', 'עילאי', 'עילי', 'רז', 'ריף', 'רום', 'עטרה', 'כתר', 'נעם', 'אביטל', 'אפרים', 'אסתר', 'רותם', 'כרמל', 'כנרת', 'ים', 'גל', 'גלי', 'אורין', 'ליב', 'אופל', 'אביה', 'אבישג', 'אורית', 'אילן', 'אילנה', 'אמונה', 'ברוך', 'דולב', 'מתן', 'נתן', 'רועי', 'שגיא', 'סער', 'גלעד', 'נדב', 'עוז', 'עוזי', 'שי', 'אוריה', 'אחינועם', 'אורלי', 'אלמוג', 'ניר', 'ניב', 'נוער', 'פלג', 'שוהם', 'שלו', 'שמשון', 'צבי', 'אביב', 'עדן', 'מעיין', 'קשת', 'נוגה', 'שיר', 'תאיר', 'תכלת', 'תדהר', 'רקפת', 'כליל', 'טליה', 'מיכאלה', 'גבריאל', 'מלאכי', 'אלישע', 'איתי', 'עידו', 'סופיה', 'קלרה', 'אמה', 'אליס', 'אמיליה', 'אוליביה', 'לונה', 'לילי', 'ליאו', 'ליאון', 'ליאם', 'מקס', 'אנה', 'בלה', 'אווה', 'אוליבר', 'לוקה', 'מילה', 'נואה', 'ניקו', 'תיאה'
